  MappedBuffer::MappedBuffer(const Ref<Buffer>& buffer, size_t byteOffset, size_t byteSize, Access access)
    : ptr(static_cast<char*>(buffer->map(byteOffset, byteSize, access))),
      byteSize(byteSize),
      buffer(buffer) {}

